<?php defined('BASEPATH')or exit('No direct script access allowed');init_head();echo '<div id="wrapper"><div class="content">';$esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'invoices/recurring'.$q);$hidden=function($action,$r=null)use($esc,$company_invoice_schedule_csrf){echo '<input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="company_invoice_schedule_csrf" value="'.$esc($company_invoice_schedule_csrf).'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';if($r)echo '<input type="hidden" name="schedule_id" value="'.(int)$r['id'].'"><input type="hidden" name="revision" value="'.(int)$r['revision'].'">';};$states=['active'=>'Ativa','paused'=>'Pausada','paused_processing'=>'Pausada com ocorrência pendente','processing'=>'Etapa pendente','completed'=>'Ciclos concluídos','cancelled'=>'Cancelada']; ?>
