<p>Modo: <?= ($detail['mode']['mode']??'issue')==='draft'?'Rascunho privado; emissão posterior exige ação explícita.':'Emissão pelo fluxo canônico.'; ?><?php if(($detail['mode']['principal_invoice_id']??null)!==null){?> · Só processar com a fatura principal #<?= (int)$detail['mode']['principal_invoice_id']; ?> quitada: <?= $detail['principal_paid']?'quitada':'aguardando quitação; próximas ocorrências não avançam'; ?><?php } ?></p>
<?php if($can_manage&&(int)$detail['actor_id']===$actor&&in_array($detail['state'],['active','processing'],true)){?><?= form_open($url());$hidden('run',$detail); ?><button type="submit"><?= $detail['state']==='processing'?'Retomar mesma ocorrência':'Processar próxima ocorrência vencida'; ?></button><?= form_close(); ?><?php } ?>
<?php if($can_manage){foreach(in_array($detail['state'],['active','processing'],true)?['pause','cancel']:(in_array($detail['state'],['paused','paused_processing'],true)?['resume','cancel']:($detail['state']==='completed'?['cancel']:[]))as$action){?><?= form_open($url());$hidden($action,$detail); ?><button type="submit"><?= ['pause'=>'Pausar e bloquear mensagens pendentes','resume'=>'Retomar com origem original','cancel'=>'Cancelar próximas emissões e mensagens pendentes'][$action]; ?></button><?= form_close(); ?><?php }} ?>
<?php if($detail['last_error']!==''){?><p role="status">Origem ou autorização exige revisão. Restaure o acesso legítimo para retomar ou cancele a série e crie outra após revisar os dados. Faturas e filas anteriores permanecem registradas.</p><?php } ?><table class="table"><thead><tr><th>Data</th><th>Etapa</th><th>Documento da ocorrência</th><th>Fila</th></tr></thead><tbody><?php foreach($detail['runs']as$run){?><tr><td><?= $esc($run['run_date']); ?></td><td><?= $esc($run['state']); ?></td><td><?php if(isset($run['draft_id'])&&$run['draft_id']!==null){?><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'invoices/drafts?draft='.(int)$run['draft_id'])); ?>">Abrir rascunho privado #<?= (int)$run['draft_id']; ?></a><?= !($run['draft_linked']??false)?' · vínculo pendente; retome a mesma ocorrência':''; ?><?php if($run['canonical_invoice_id']!==null){?> · <?php }}if($run['canonical_invoice_id']!==null){?><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'invoices/list_invoices/'.(int)$run['canonical_invoice_id'])); ?>">Abrir fatura</a><?php }elseif(!isset($run['draft_id'])||$run['draft_id']===null){?>Emissão ainda não confirmada no vínculo<?php } ?></td><td><?= isset($run['draft_id'])?'Sem envio automático de rascunho':($run['canonical_queue_id']===null?'Fila ainda não confirmada':('Fila registrada #'.(int)$run['canonical_queue_id'].($run['queue_id']===null?'; vínculo pendente':'').'; entrega não comprovada')); ?></td></tr><?php } ?></tbody></table></div><?php } ?>
